begin;
create extension if not exists pgtap with schema extensions;
select plan(14);
insert into auth.users(id,email) values ('71111111-1111-1111-1111-111111111111','rating-a@example.test'),('72222222-2222-2222-2222-222222222222','rating-b@example.test'),('73333333-3333-3333-3333-333333333333','rating-c@example.test'),('74444444-4444-4444-4444-444444444444','rating-d@example.test');
insert into public.profiles(id,owner_id,display_name) values ('7aaaaaaa-1111-1111-1111-111111111111','71111111-1111-1111-1111-111111111111','A'),('7bbbbbbb-2222-2222-2222-222222222222','72222222-2222-2222-2222-222222222222','B'),('7ccccccc-3333-3333-3333-333333333333','73333333-3333-3333-3333-333333333333','C'),('7ddddddd-4444-4444-4444-444444444444','74444444-4444-4444-4444-444444444444','D');
insert into public.profile_areas values ('7aaaaaaa-1111-1111-1111-111111111111','Test area',40,-74,'US'),('7bbbbbbb-2222-2222-2222-222222222222','Test area',40,-74,'US'),('7ccccccc-3333-3333-3333-333333333333','Test area',40,-74,'US'),('7ddddddd-4444-4444-4444-444444444444','Test area',40,-74,'US');
set local role authenticated;
select set_config('request.jwt.claim.sub','72222222-2222-2222-2222-222222222222',true);
select lives_ok($$select public.save_rated_profile('B','chess_com_rapid',1500)$$,'owner adds rating');
select set_config('request.jwt.claim.sub','73333333-3333-3333-3333-333333333333',true);
select public.save_rated_profile('C','lichess_rapid',1500);
select set_config('request.jwt.claim.sub','71111111-1111-1111-1111-111111111111',true);
select public.save_search_area('Test area',40,-74,'US',5);
select is(jsonb_array_length(public.search_players(40,-74,5,null,20,'chess_com_rapid',1500,1500)->'players'),1,'inclusive bounds exclude different source and unrated');
select is(jsonb_array_length(public.search_players(40,-74,5,null,20,'chess_com_blitz',null,null)->'players'),0,'format mismatch excluded');
select is(jsonb_array_length(public.search_players(40,-74,5,null,20)->'players'),3,'unfiltered includes unrated');
select throws_ok($$select public.save_rated_profile('Bad','chess_com_rapid',0)$$,'22023',null,'zero rejected atomically');
select is((select display_name from public.get_own_profile()),'A','invalid rating preserves name');
select throws_ok($$select public.save_search_filters(5,'chess_com_rapid',1600,1400)$$,'22023',null,'reversed bounds rejected');
select is(public.save_search_filters(5,'chess_com_rapid',1400,null)->'rating'->>'minimum','1400','one-sided filter saved');
select is(public.get_discovery_settings()->'rating'->>'kind','chess_com_rapid','filter reload persists key');
select is(public.save_search_filters(5,null,null,null)->'rating','null'::jsonb,'clear removes rating constraint');
select set_config('request.jwt.claim.sub','72222222-2222-2222-2222-222222222222',true);
select lives_ok($$select public.save_own_profile_area('Updated area',40,-74,'US',5)$$,'area editing retains expanded profile projection');
select is((select rating->>'value' from public.get_own_profile()),'1500','area change preserves rating');
select is((select rating from public.save_rated_profile('B',null,null)),null::jsonb,'removing rating restores unrated');
select throws_ok($$select * from public.profile_ratings$$,'42501',null,'direct writes/reads cannot bypass owner RPC');
select * from finish();
rollback;
